// === Inspired by 'Vortex' by 'POSTHELIOS' ===
// Created as variant #4 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
let xmotion = 0;
let ymotion = 0;
let zmotion = 0;

function setup() {
  createCanvas(1024, 768);

  colorMode(HSB, 360, 255, 255);

  background(10, 10, 15, 6);
  noStroke();

  strokeWeight(2.5);

  noiseDetail(7, 0.5);
}

let radius = 32;

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

 // background(0, 0, 0, 1);
  noStroke();

  fill(0, 0, 0, 32);
	rect(0, 0, width, height);

	noFill();

  let count = 12;

  let i = 0; let j = 0;

  let x =  width / 2 + (sin(xmotion * 0.5) * width / 16);
  let y = height / 2 + (cos(zmotion * 0.75) * height / 16);

  for (j = 0; j < 1; j += 0.002) {
		let jnorm_j = abs(0.5 - j) * 2;
  for (i = 0; i < count; i += 1) {
    let norm_i = i / count;
    let unit_i = 1 / count;

    let inorm_i = abs(0.5 - norm_i) * 2;

    let n = noise(inorm_i + xmotion, jnorm_j + ymotion) / 128;

		let rad1 = radius + cos(xmotion * PI * 4 + inorm_i * PI * 32 + jnorm_j * PI * 8) / (0.4 + abs(sin(xmotion) * 2));
		let rad2 = radius + sin(ymotion * PI * 4 + inorm_i * PI * 32 + jnorm_j * PI * 8) / (0.4 + abs(cos(zmotion) * 2));

    let cx = rad1 * sin(norm_i * PI * 2 + n * 4 + xmotion + (j * PI * 2)) + sin(xmotion*2) * 24;
    let cy = rad1 * cos(norm_i * PI * 2 + n * 4 + ymotion + (j * PI * 2)) + cos(ymotion*2) * 24;

    let cx2 = rad2 * sin((unit_i + norm_i) * PI * 2 + xmotion + (j * PI * 2)) + sin(xmotion*2) * 24;
    let cy2 = rad2 * cos((unit_i + norm_i) * PI * 2 + ymotion + (j * PI * 2)) + cos(ymotion*2) * 24;

    //stroke(0, 0, 0, 128);
   // line(x + cx, y + cy, x + cx2, y + cy2);
    line(x + cx / 2, y + cy / 2, x + cx2 / 2, y + cy2 / 2);
		stroke(192 + inorm_i * 128 + jnorm_j * 128, 128 * (1-j), 256, 256 * (n * 32));

    line(x + cx / j, y + cy / j, x + cx2 / j, y + cy2 / j);

    noStroke();
  }
  }

  xmotion += 0.01;
  ymotion += 0.01;
	zmotion += 0.02;
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
